-- Nuevas misiones complementarias (para testing adicional)
INSERT INTO missions (id, level_id, name, description, image_id, order_num, max_stars, is_active, created_at, updated_at) VALUES
(gen_random_uuid(), (SELECT id FROM levels WHERE level_type = 'normal' LIMIT 1), 'Misión de Prueba: Conceptos Avanzados', 'Contenidos complementarios para testing', '4891df8a-7353-4399-8c14-c3a55e2a738f', 99, 3, true, NOW(), NOW()),
(gen_random_uuid(), (SELECT id FROM levels WHERE level_type = 'normal' LIMIT 1 OFFSET 1), 'Misión de Prueba: Casos de Estudio', 'Análisis de casos reales', '81755fb5-9edf-4389-b060-a7f9b6ff681d', 98, 3, true, NOW(), NOW()),
(gen_random_uuid(), (SELECT id FROM levels WHERE level_type = 'normal' LIMIT 1 OFFSET 2), 'Misión de Prueba: Evaluación Práctica', 'Ejercicios prácticos aplicados', 'cd938867-a5eb-48f5-a45b-deaed387db5f', 97, 3, true, NOW(), NOW());

-- Nuevos contenidos de misión
INSERT INTO mission_items (id, mission_id, title, image_id, benefits, content_badges, detail, order_num, created_at, updated_at)
SELECT 
  gen_random_uuid(),
  m.id,
  'Contenido de Prueba: ' || m.name,
  '4891df8a-7353-4399-8c14-c3a55e2a738f',
  '<p>Contenido complementario para testing</p>',
  '["Testing", "Prueba"]',
  '<p>Este es un contenido adicional para pruebas. Complementa el backup con material de testing.</p>',
  1,
  NOW(),
  NOW()
FROM missions m
WHERE m.name LIKE 'Misión de Prueba:%'
AND order_num IN (99, 98, 97);

